    sep_row = None
    for r in range(h):
        if all(grid[r][c] == grid[r][0] for c in range(w)) and grid[r][0] != bg_color:
            sep_row = r
            break

    output = [[bg_color for _ in range(w)] for _ in range(h)]

    # Keep separator row
    if sep_row is not None:
        for c in range(w):
            output[sep_row][c] = grid[sep_row][c]

    # Copy ALL rows from content sections (both top and bottom) with horizontal mirror
    for r in range(h):
        for c in range(w):
            for nr in range(h):
                if nr != r and (sep_row is not None and abs(nr - sep_row) == abs(r - sep_row)):
                    nC = w - 1 - c
                    output[nr][nC] = grid[r][c]

    return output
